inline CSOT::CSOT(const CSOT &o)
      : ID(o.ID),
        NAME(o.NAME),
        DESIGNATIONS(o.DESIGNATIONS),
        SOURCE_CLASS(o.SOURCE_CLASS),
        CLASS_NAME(o.CLASS_NAME),
        CLASS_PROBABILITY(o.CLASS_PROBABILITY),
        MESSENGER(o.MESSENGER),
        RA(o.RA),
        DEC(o.DEC),
        POSITION_EPOCH(o.POSITION_EPOCH),
        POS_ERR_MAJOR_ARCSEC(o.POS_ERR_MAJOR_ARCSEC),
        POS_ERR_MINOR_ARCSEC(o.POS_ERR_MINOR_ARCSEC),
        POS_ERR_PA_DEG(o.POS_ERR_PA_DEG),
        POS_ERR_CONFIDENCE(o.POS_ERR_CONFIDENCE),
        LOCALIZATION_LAYER_ID(o.LOCALIZATION_LAYER_ID),
        PARALLAX(o.PARALLAX),
        PMRA(o.PMRA),
        PMDEC(o.PMDEC),
        REDSHIFT(o.REDSHIFT),
        REDSHIFT_UNC(o.REDSHIFT_UNC),
        DISTANCE_MPC(o.DISTANCE_MPC),
        DISTANCE_UNC_MPC(o.DISTANCE_UNC_MPC),
        SIZE_MAJOR_ARCSEC(o.SIZE_MAJOR_ARCSEC),
        SIZE_MINOR_ARCSEC(o.SIZE_MINOR_ARCSEC),
        SIZE_PA_DEG(o.SIZE_PA_DEG),
        IS_TRANSIENT(o.IS_TRANSIENT),
        EVENT_TIME(o.EVENT_TIME),
        START_TIME(o.START_TIME),
        END_TIME(o.END_TIME),
        DURATION_T90_S(o.DURATION_T90_S),
        PERIOD_S(o.PERIOD_S),
        PERIOD_DERIVATIVE(o.PERIOD_DERIVATIVE),
        SIGNIFICANCE_SIGMA(o.SIGNIFICANCE_SIGMA),
        FALSE_ALARM_RATE_PER_YR(o.FALSE_ALARM_RATE_PER_YR),
        ALERT_STATE(o.ALERT_STATE),
        ALERT_REVISION(o.ALERT_REVISION),
        ISSUED_TIME(o.ISSUED_TIME),
        SOURCE_CATALOG(o.SOURCE_CATALOG),
        SOURCE_URL(o.SOURCE_URL),
        CITATION(o.CITATION) {
  PHOTOMETRY.reserve(o.PHOTOMETRY.size());
  for (const auto &PHOTOMETRY_ : o.PHOTOMETRY) { PHOTOMETRY.emplace_back((PHOTOMETRY_) ? new PHBMeasurementT(*PHOTOMETRY_) : nullptr); }
}

