inline const CSO *GetCSO(const void *buf) {
  return ::flatbuffers::GetRoot<CSO>(buf);
}

inline const CSO *GetSizePrefixedCSO(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<CSO>(buf);
}

inline const char *CSOIdentifier() {
  return "$CSO";
}

inline bool CSOBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, CSOIdentifier());
}

inline bool SizePrefixedCSOBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, CSOIdentifier(), true);
}

template <bool B = false>
inline bool VerifyCSOBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<CSO>(CSOIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedCSOBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<CSO>(CSOIdentifier());
}

inline void FinishCSOBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<CSO> root) {
  fbb.Finish(root, CSOIdentifier());
}

inline void FinishSizePrefixedCSOBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<CSO> root) {
  fbb.FinishSizePrefixed(root, CSOIdentifier());
}

inline std::unique_ptr<CSOT> UnPackCSO(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<CSOT>(GetCSO(buf)->UnPack(res));
}

inline std::unique_ptr<CSOT> UnPackSizePrefixedCSO(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<CSOT>(GetSizePrefixedCSO(buf)->UnPack(res));
}

